import React, { useState } from "react";
import { API } from "../config";
import "./Home.css";   // ✅ Import your CSS

export default function Home() {
  const [vehicle, setVehicle] = useState("");
  const [challans, setChallans] = useState([]);

  const fetchChallans = async () => {
    if (!vehicle) return alert("Enter vehicle number");
    const res = await fetch(`${API}/challan/vehicle/${vehicle}`);
    const data = await res.json();
    if (data.error) alert(data.error);
    else setChallans(data);
  };

  return (
    <div className="home-container">
      <h3 className="text-center mb-4">Search Challans by Vehicle Number</h3>

      <div className="search-form">
        <input
          className="form-control"
          placeholder="Enter vehicle number"
          value={vehicle}
          onChange={(e) => setVehicle(e.target.value)}
        />
        <button className="btn btn-primary" onClick={fetchChallans}>
          Search
        </button>
      </div>

      {challans.length > 0 && (
        <div className="results">
          <h5 className="mt-4 mb-3">Results for: {vehicle}</h5>
          <table className="table table-bordered table-striped">
            <thead className="table-dark">
              <tr>
                <th>#</th>
                <th>Vehicle</th>
                <th>Cause</th>
                <th>Fine</th>
                <th>Status</th>
                <th>Issue Date</th>
                <th>Due Date</th>
                <th>Address</th>
              </tr>
            </thead>
            <tbody>
              {challans.map((c, i) => (
                <tr key={c._id}>
                  <td>{i + 1}</td>
                  <td>{c.vehicleNumber}</td>
                  <td>{c.cause}</td>
                  <td>{c.fine}</td>
                  <td>{c.status}</td>
                  <td>{c.issueDate}</td>
                  <td>{c.dueDate}</td>
                  <td>{c.address}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
